    if (UninitFillN(dst, 0, x, tag) != dst || object.RefCount != 5) ok = false;
    if (!ok) { std::printf("005f7a1d_TEST FAIL\n"); return 1; }
    std::printf("005f7a1d_TEST PASS\n");
    return 0;
}

